package com.fasterxml.jackson.core.io;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.util.BufferRecycler;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

public class IOContext_releaseBase64Buffer_TriageGen0Test {

    private BufferRecycler _bufferRecycler;
    private IOContext _ioContext;
    private byte[] _testBuffer;

    @Before
    public void setUp() {
        _bufferRecycler = mock(BufferRecycler.class);
        // IOContext constructor: public IOContext(BufferRecycler br, Object sourceRef, boolean managedResource)
        _ioContext = new IOContext(_bufferRecycler, new Object(), true);
        _testBuffer = _ioContext.allocBase64Buffer();
    }

    @Test
    public void testReleaseBase64Buffer_NullBuffer_DoesNothing() {
        // Passing null should trigger the 'if (buf != null)' check and skip the body
        _ioContext.releaseBase64Buffer(null);

        verify(_bufferRecycler, never()).releaseByteBuffer(any(), any());
    }

    @Test
    public void testReleaseBase64Buffer_Success() {
        // Ensure the buffer is valid for the first release
        byte[] bufToRelease = _testBuffer;

        _ioContext.releaseBase64Buffer(bufToRelease);

        // Verify the recycler was called with correct arguments
        verify(_bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, bufToRelease);
    }

    @Test(expected = IllegalStateException.class)
    public void testReleaseBase64Buffer_VerifyReleaseFails() {
        // Create a dummy buffer that wasn't allocated by this IOContext to trigger _verifyRelease failure
        byte[] wrongBuffer = new byte[10];

        // This should throw an exception inside _verifyRelease
        _ioContext.releaseBase64Buffer(wrongBuffer);
    }

    @Test(expected = IllegalStateException.class)
    public void testReleaseBase64Buffer_DoubleReleaseFails() {
        // First release: should succeed
        _ioContext.releaseBase64Buffer(_testBuffer);

        // Second release: _base64Buffer is now null, so _verifyRelease should fail 
        // because it compares the passed buffer against a null _base64Buffer
        _ioContext.releaseBase64Buffer(_testBuffer);
    }

    @Test
    public void testReleaseBase64Buffer_ReleaseOnceOnly() {
        // First release
        _ioContext.releaseBase64Buffer(_testBuffer);
        verify(_bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, _testBuffer);

        // After first release, _base64Buffer is set to null.
        // If we try to release a different buffer, it should fail verification.
        // If we try to release null, it should do nothing.
        _ioContext.releaseBase64Buffer(null);

        // Verify no second call to recycler happened
        verify(_bufferRecycler, Mockito.times(1)).releaseByteBuffer(any(), any());
    }
}
